#pragma once

#include "../src/terrain_collision/terrain_collision_artifact.h"
#include <algorithm>
#include <map>
#include <mutex>

// Generated bytes only. Each operation holds the mutex, including the complete
// no-replace move, so publication race tests share the same atomic store.
class TerrainCollisionMemoryStorage final
    : public matter::terrain_collision::detail::ArtifactStorage {
    struct File {
        std::vector<std::uint8_t> bytes;
        std::uint64_t revision;
    };
    std::mutex mutex_;
    std::map<std::filesystem::path, File> files_;
    std::uint64_t revision_ = 0;
    static std::filesystem::path key(const std::filesystem::path& path) {
        return path.lexically_normal();
    }
public:
    bool exists(const std::filesystem::path& path, std::error_code& error) override {
        std::lock_guard<std::mutex> lock(mutex_);
        error.clear();
        return files_.count(key(path)) != 0;
    }
    bool exists(const std::filesystem::path& path) {
        std::error_code error;
        return exists(path, error);
    }
    std::uintmax_t file_size(const std::filesystem::path& path,
                            std::error_code& error) override {
        std::lock_guard<std::mutex> lock(mutex_);
        auto found = files_.find(key(path));
        error.clear();
        if (found == files_.end()) {
            error = std::make_error_code(std::errc::no_such_file_or_directory);
            return std::uintmax_t(-1);
        }
        return found->second.bytes.size();
    }
    bool read(const std::filesystem::path& path, std::size_t offset,
              std::size_t count, std::uint8_t* destination) override {
        std::lock_guard<std::mutex> lock(mutex_);
        auto found = files_.find(key(path));
        if (found == files_.end() || offset > found->second.bytes.size() ||
            count > found->second.bytes.size() - offset) return false;
        if (count) std::copy_n(found->second.bytes.data() + offset, count, destination);
        return true;
    }
    bool write(const std::filesystem::path& path,
               const std::vector<std::uint8_t>& bytes) override {
        std::lock_guard<std::mutex> lock(mutex_);
        files_[key(path)] = File{bytes, ++revision_};
        return true;
    }
    void remove(const std::filesystem::path& path) noexcept override {
        std::lock_guard<std::mutex> lock(mutex_);
        files_.erase(key(path));
    }
    bool remove(const std::filesystem::path& path, std::error_code& error) {
        std::lock_guard<std::mutex> lock(mutex_);
        error.clear();
        return files_.erase(key(path)) != 0;
    }
    void remove_all(const std::filesystem::path& root, std::error_code& error) {
        std::lock_guard<std::mutex> lock(mutex_);
        error.clear();
        const auto prefix = key(root).generic_string() + "/";
        for (auto it = files_.begin(); it != files_.end();) {
            if (it->first == key(root) || it->first.generic_string().find(prefix) == 0)
                it = files_.erase(it);
            else ++it;
        }
    }
    void create_directories(const std::filesystem::path&) {}
    std::uint32_t move(const std::filesystem::path& source,
                       const std::filesystem::path& destination,
                       bool replace) override {
        std::lock_guard<std::mutex> lock(mutex_);
        auto from = files_.find(key(source));
        if (from == files_.end()) return 2u;
        if (!replace && files_.count(key(destination))) return 183u;
        files_.insert_or_assign(key(destination), std::move(from->second));
        files_.erase(from);
        return 0u;
    }
    std::uint64_t last_write_time(const std::filesystem::path& path) {
        std::lock_guard<std::mutex> lock(mutex_);
        return files_.at(key(path)).revision;
    }
    std::vector<std::filesystem::path> paths_below(const std::filesystem::path& root) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<std::filesystem::path> result;
        const auto prefix = key(root).generic_string() + "/";
        for (const auto& entry : files_)
            if (entry.first.generic_string().find(prefix) == 0)
                result.push_back(entry.first);
        return result;
    }
};
